  add(/底辺 (\d+)cm・高さ (\d+)cm の 三角形の 面積/, function (m) { return '三角形 ＝ 底辺 × 高さ ÷ 2：' + m[1] + '×' + m[2] + '÷2＝' + N(m[1]) * N(m[2]) / 2 + 'cm²。同じ 三角形 2つで 平行四辺形に なるので ÷2。'; });
